#!/usr/bin/env node
/**
 * fix-generic-descriptions.cjs
 * Replaces generic placeholder descriptions with specific clinical text.
 * Usage:  node scripts/fix-generic-descriptions.cjs [--dry-run]
 */
const admin = require('firebase-admin');
const path  = require('path');
const SA    = path.resolve(__dirname, '../serviceAccount-target.json');
admin.initializeApp({ credential: admin.credential.cert(SA), projectId: 'med-peptides-app' });
const db = admin.firestore();
const DRY = process.argv.includes('--dry-run');
const MARKER = 'premium-grade research peptide designed for cellular signaling';

const D = {
  // ── A ──
  'selank':         'Selank is a synthetic anxiolytic heptapeptide analogue of endogenous tuftsin (Thr-Lys-Pro-Arg). It modulates the GABAergic system and stimulates BDNF and enkephalin synthesis, producing anxiolytic, nootropic, and immunomodulatory effects without sedation or dependence. Clinical applications: generalised anxiety, cognitive enhancement, and immune optimisation.',
  'semax':          'Semax is a synthetic ACTH4–7 analogue heptapeptide that upregulates BDNF, NGF, and VEGF expression in the CNS via the melanocortin system. It enhances hippocampal long-term potentiation, neuroprotection against ischaemic injury, and executive cognitive function. Delivered intranasally via the nose-to-brain transcribiform route for rapid CNS bioavailability.',
  'semax-selank':   'Fixed-dose intranasal combination of Semax (ACTH4-7 analogue) and Selank (tuftsin analogue). Semax drives BDNF/NGF upregulation and cognitive enhancement; Selank provides anxiolysis and immunomodulation via GABAergic and enkephalin pathways. Synergistic nootropic-anxiolytic stack with no sedation, tolerance, or addiction risk.',
  'selank-semax':   'Fixed-dose intranasal combination of Semax (ACTH4-7 analogue) and Selank (tuftsin analogue). Semax drives BDNF/NGF upregulation and cognitive enhancement; Selank provides anxiolysis and immunomodulation via GABAergic and enkephalin pathways. Synergistic nootropic-anxiolytic stack with no sedation, tolerance, or addiction risk.',
  'adipotide-2mg':  'Adipotide is a peptidomimetic targeting the ANXA2/prohibitin receptor complex on white adipose vasculature, inducing selective apoptosis of fat-depot endothelial cells. Preclinical data demonstrates significant visceral and subcutaneous fat reduction while preserving lean mass, without systemic vascular effects.',
  'aicar-50-mg':    'AICAR is a cell-permeable AMP kinase (AMPK) activator that mimics the metabolic effects of exercise at the molecular level. It upregulates GLUT4 expression, drives mitochondrial biogenesis via PGC-1α, and improves insulin sensitivity. Applied in metabolic syndrome, endurance performance, and fat-oxidation research protocols.',
  'aod-9604':       'AOD-9604 is the C-terminal hGH fragment (aa 177–191) responsible for the lipolytic activity of growth hormone, without its proliferative or diabetogenic side effects. It stimulates lipolysis via beta-3 adrenergic receptors and inhibits lipogenesis, providing a targeted and safe fat-metabolism intervention.',
  'alprostadil':    'Alprostadil (PGE₁) relaxes corpus cavernosum smooth muscle via cAMP-mediated pathways to produce penile erection, and inhibits platelet aggregation. Indicated for vasculogenic and mixed-etiology erectile dysfunction, and critical limb ischaemia. Reconstituted for intracavernosal or intraurethral administration.',
  'amlexanox':      'Amlexanox is a selective TBK1 and IKKε inhibitor that blocks obesity-driven metabolic inflammation. By reducing energy-expenditure suppression, it improves insulin sensitivity and glucose tolerance. Originally developed for aphthous ulcers; now researched extensively for type 2 diabetes, NASH, and obesity-driven inflammation.',
  'alpha-tocopherol-acetate': 'Alpha-Tocopherol Acetate is the esterified, shelf-stable form of Vitamin E. As the primary lipophilic chain-breaking antioxidant in cellular membranes, it terminates lipid-peroxidation cascades, protects LDL from oxidation, and modulates PKC signalling. Essential for skin barrier integrity, neurological protection, and immune function.',
  'ammonia-solution': 'Ammonia Solution (NH₄OH) is a compounding excipient and pH-adjusting agent used in pharmaceutical manufacturing to alkalise poorly water-soluble compounds, buffer injectable formulations to physiological pH, and as a preservative in selected compounding applications. Pharma-grade purity with full CoA documentation.',
  'anhydrous-lanolin': 'Anhydrous Lanolin (Adeps Lanae) is a refined wool-wax ester emollient, emulsifier, and penetration enhancer. Its w/o emulsification properties absorb up to 200% of its weight in water, forming stable non-greasy topical bases that significantly enhance active pharmaceutical ingredient skin penetration.',
  'amphotericin-b': 'Amphotericin B is a polyene macrolide antifungal that binds ergosterol in fungal cell membranes, forming ion-permeable pores leading to cell death. Gold standard for severe systemic mycoses including aspergillosis, cryptococcosis, and disseminated candidiasis. Supplied as a lyophilised powder for reconstitution.',
  'atropine-sulfate': 'Atropine Sulfate is a competitive muscarinic acetylcholine receptor antagonist from Atropa belladonna. It blocks parasympathetic activity (mydriasis, reduced secretions, tachycardia, bronchodilation). Indicated for bradycardia, organophosphate poisoning, pre-anaesthetic medication, and ophthalmic procedures. Low-dose 0.01% is used for paediatric myopia progression control.',
  'acetylhexapeptide': 'Acetylhexapeptide-3 (Argireline) is a synthetic hexapeptide that competitively inhibits the SNARE protein complex required for neurotransmitter vesicle fusion. By reducing acetylcholine release at neuromuscular junctions, it produces a topical botulinum-toxin-like muscle relaxation, visibly reducing dynamic expression wrinkles without injection.',

  // ── B ──
  'bpc':            'BPC-157 (Body Protection Compound) is a synthetic pentadecapeptide derived from human gastric juice. It activates VEGFR2/eNOS-mediated angiogenesis, upregulates growth hormone receptors, and modulates dopaminergic and serotonergic systems. Primary indications: GI mucosal repair, tendon and ligament healing, and systemic tissue regeneration.',
  'bpc-157':        'BPC-157 is a 15-amino acid cytoprotective peptide derived from human gastric juice protein. It upregulates VEGF and eNOS to accelerate angiogenesis, modulates the GH receptor system, and exhibits anti-inflammatory, GI-protective, and neuroprotective properties. Clinically applied for inflammatory bowel disease, musculoskeletal repair, and systemic healing protocols.',
  'bpc-157-semaglutide': 'Combination of BPC-157 (tissue repair peptidomimetic) and Semaglutide (GLP-1 receptor agonist). BPC-157 addresses GI mucosal side effects associated with GLP-1 agonists while Semaglutide drives weight loss and glycaemic control. Synergistic protocol for medically supervised weight management with improved GI tolerability.',
  'bpc-157-tb-500-ghk-cu': 'Triple regenerative peptide stack combining BPC-157 (GI/tissue repair via VEGFR2/eNOS), TB-500 (actin-mediated cell migration and angiogenesis), and GHK-Cu (collagen synthesis stimulation and antioxidant signalling). Together they address the complete tissue repair cascade from initial inflammation resolution through structural matrix rebuilding.',
  'bpc-157-tb-500-ghk-cu-kpv': 'Comprehensive 4-peptide regenerative stack: BPC-157 (angiogenesis and GI repair), TB-500 (actin-mediated healing), GHK-Cu (collagen remodelling), and KPV (NF-κB anti-inflammatory modulation). Designed for complex tissue repair, post-surgical recovery, and chronic inflammatory conditions.',
  'bioniq_anti_aging_and_immunity_bundle_bundle': 'Curated peptide stack targeting hallmarks of ageing — telomere attrition, cellular senescence, mitochondrial dysfunction, and immune dysregulation. Each component is independently HPLC-verified for purity and potency.',
  'bioniq_bpc_157_kpv_capsule': 'Oral combination of BPC-157 (VEGFR2/eNOS-mediated mucosal and tissue repair) and KPV (α-MSH fragment targeting NF-κB anti-inflammation). Synergistic action on gastrointestinal barrier integrity, systemic inflammation reduction, and mucosal healing, with excellent oral bioavailability.',
  'bioniq_cellular_repair_and_energy_bundle_bundle': 'Precision peptide stack activating mitochondrial biogenesis, cellular autophagy, and tissue repair via AMPK/PGC-1α pathways combined with growth-factor mimetics. Designed to restore cellular vitality and accelerate recovery from metabolic and oxidative stress.',
  'bioniq_glp_3_single_use_pen_30_mg': 'GLP-3 is a proglucagon-derived incretin-related peptide under research for its distinct roles in gut hormone signalling, gastric emptying modulation, and enteroendocrine axis interactions. Potential clinical applications include obesity, type 2 diabetes, and gut health optimisation, complementary to GLP-1 pathways.',
  'bioniq_health_optimisation_bundle_bundle': 'Comprehensive wellness stack combining validated peptides addressing longevity, metabolic health, immune function, and cognitive performance. Each component targets evidence-based biological pathways for systemic health optimisation.',
  'bioniq_oxytocin_methylene_blue_nasal_spray': 'Intranasal combination of Oxytocin (hypothalamic neuropeptide) and Methylene Blue (mitochondrial electron shuttle) via the nose-to-brain transcribiform pathway. Oxytocin modulates HPA-axis stress response and promotes neuroplasticity; Methylene Blue improves ATP production and reduces oxidative stress.',
  'bioniq_pt_141_oxytocin_nasal_spray': 'Intranasal combination of Bremelanotide (PT-141) and Oxytocin targeting central melanocortin pathways. PT-141 activates hypothalamic MC3R/MC4R receptors for arousal independent of vascular mechanisms; Oxytocin reinforces prosocial bonding and reduces performance anxiety.',
  'bioniq_skin_tissue_regeneration_stack_bundle': 'Regenerative peptide stack combining growth factors and structural repair peptides targeting collagen synthesis, angiogenesis, fibroblast proliferation, and anti-inflammatory pathways for skin rejuvenation, post-procedure recovery, and chronic wound management.',
  'bioniq_tb_500_thymosin_beta_4_single_use_pen_15_mg': 'Thymosin Beta-4 (TB-500) is a 43-amino acid actin-sequestering peptide that modulates actin polymerisation, promotes cell migration and angiogenesis, and reduces fibrotic scarring. It upregulates MMPs and IGF-1 for musculoskeletal, tendon, and cardiac tissue repair. Widely used in athletic recovery and post-injury rehabilitation.',
  'bioniq_wolverine_repair_bundle_bundle': 'High-potency recovery peptide stack combining BPC-157, TB-500, and complementary repair peptides to maximise musculoskeletal, tendon, and ligament regeneration following acute injury or intensive training loads.',
  'bupropion-hcl':  'Bupropion HCl is a selective noradrenaline-dopamine reuptake inhibitor (NDRI) and nicotinic acetylcholine receptor antagonist. It elevates synaptic dopamine and noradrenaline levels to treat major depressive disorder, and reduces nicotine craving for smoking cessation. Also used off-label for ADHD and as an augmentation agent in weight management protocols.',

  // ── C ──
  'cagrilintide':   'Cagrilintide is a long-acting amylin analogue that binds amylin and calcitonin receptors in the hypothalamic area postrema to reduce food intake, slow gastric emptying, and induce satiety independently of GLP-1 pathways. In combination with semaglutide (CagriSema), it provides superior weight reduction vs either monotherapy.',
  'cagrilintide-semaglutide': 'CagriSema combines Cagrilintide (amylin analogue) and Semaglutide (GLP-1 receptor agonist), targeting complementary satiety pathways. Phase 3 data (REDEFINE trials) demonstrates weight reductions exceeding 25% — among the highest reported for any pharmacological intervention — with improved glycaemic and cardiovascular outcomes.',
  'calcium-pantothenate-ph-eur': 'Calcium Pantothenate (Vitamin B5) is an essential coenzyme A precursor. It supports fatty acid synthesis and oxidation, adrenal steroid production, and is required for the biosynthesis of acetylcholine. Used in compounding as an active ingredient in energy metabolism formulations and as a pharmaceutical-grade excipient.',
  'cardiogen':      'Cardiogen is a tetrapeptide (Ala-Glu-Asp-Gly) bioregulator developed by the St. Petersburg Institute of Bioregulation. It selectively stimulates cardiac gene expression, promotes cardiomyocyte protein synthesis, and reduces myocardial inflammation and fibrosis. Applied in cardiovascular ageing, post-myocardial infarction recovery, and heart protection protocols.',
  'cartalax':       'Cartalax is a tripeptide (Ala-Glu-Asp) cartilage bioregulator that stimulates chondrocyte differentiation, proteoglycan production, and cartilage matrix synthesis. It reduces degenerative joint disease progression and supports articular cartilage regeneration, making it applicable in osteoarthritis, post-surgical joint recovery, and athletic joint protection.',
  'cerebrolysin':   'Cerebrolysin is a standardised neuropeptide preparation derived from porcine brain protein hydrolysate, containing low-molecular-weight peptides that cross the blood-brain barrier. It mimics the action of neurotrophic factors (BDNF, NGF), promotes neuroplasticity, supports neuroprotection, and is clinically used for Alzheimer\'s disease, post-stroke recovery, and traumatic brain injury rehabilitation.',
  'cjc':            'CJC is a growth hormone-releasing peptide analogue that stimulates pituitary GHRH receptors to increase pulsatile GH secretion. Used in GH restoration protocols for adults with age-related GH decline, metabolic optimisation, and body composition improvement.',
  'cjc-1295':       'CJC-1295 is a tetrasubstituted GHRH analogue (with DAC) engineered for extended half-life via albumin binding. It produces sustained, pulsatile GH release over 7–14 days per dose, restoring youthful GH patterns without tachyphylaxis. Applied in anti-ageing protocols, muscle mass restoration, fat loss, and sleep-quality improvement.',
  'cjc-1295-dac':   'CJC-1295 with DAC (Drug Affinity Complex) is an engineered GHRH analogue that binds endogenous albumin via a maleimido-propionic acid moiety, extending its plasma half-life to 7–10 days. Produces stable, sustained pulsatile GH release. Preferred for once-weekly GH optimisation protocols in anti-ageing medicine.',
  'cjc-1295-ipamorelin': 'Combination GHRH/GHRP stack: CJC-1295 amplifies hypothalamic GHRH signalling for sustained GH release; Ipamorelin selectively agonises pituitary ghrelin receptors to pulse GH without elevating cortisol or prolactin. Together they produce synergistic, physiological GH pulses that optimise body composition, recovery, sleep, and IGF-1 levels.',
  'cjc-1295-ipamorelin-dsip': 'Triple stack combining CJC-1295 (GHRH amplification), Ipamorelin (selective ghrelin receptor agonist), and DSIP (Delta Sleep-Inducing Peptide). CJC-1295 + Ipamorelin produce synergistic GH pulses; DSIP enhances slow-wave sleep depth and normalises cortisol rhythm, maximising nocturnal GH secretion and recovery.',
  'cjc-1295-no-dac': 'CJC-1295 No DAC (Modified GRF 1-29) is a stabilised GHRH analogue with a 30-minute half-life, producing clean pulsatile GH release when dosed with meals or pre-sleep. Preferred for twice-daily protocols that mimic natural GH secretion patterns without albumin binding.',
  'cjc-1295-no-dac-ipamorelin': 'Preferred 2-peptide GH optimisation stack: CJC-1295 No DAC (modified GRF 1-29) amplifies the GHRH axis; Ipamorelin selectively agonises pituitary ghrelin receptors. Together they produce clean, pulsatile, synergistic GH release without cortisol or prolactin elevation. Gold standard for anti-ageing GH restoration protocols.',
  'cjc-1295-no-dac-ipamorelin-bpc-157': '3-peptide stack combining CJC-1295 No DAC/Ipamorelin GH optimisation with BPC-157 tissue repair. The GH axis peptides drive body composition and IGF-1; BPC-157 accelerates musculoskeletal and GI healing via VEGFR2/eNOS pathways, making this a complete performance recovery and optimisation protocol.',
  'cjc-1295-no-dac-ipamorelin-sermorelin': 'Comprehensive GHRH stack: Sermorelin (GHRH 1-29 native analogue) + CJC-1295 No DAC (stabilised GHRH analogue) + Ipamorelin (selective GHRP) produce maximal synergistic pulsatile GH release with full physiological patterning. Designed for advanced GH restoration and anti-ageing medicine.',
  'clobetasol-propionate': 'Clobetasol Propionate is a super-potent Class I corticosteroid that binds glucocorticoid receptors with high affinity, producing potent vasoconstriction, anti-inflammatory, and immunosuppressive effects. Indicated for severe plaque psoriasis, lichen planus, and refractory inflammatory dermatoses. Applied topically at 0.05% concentration.',
  'cyclosporine-a': 'Cyclosporine A is a calcineurin inhibitor immunosuppressant that blocks T-lymphocyte activation by preventing IL-2 transcription. Applied topically (0.2–2%) for severe dry eye disease, atopic keratoconjunctivitis, and vernal keratoconjunctivitis. Systemic use for organ transplant rejection prevention and autoimmune dermatological conditions.',

  // ── D ──
  'dexamethasone':  'Dexamethasone is a potent long-acting synthetic glucocorticoid with 25× the anti-inflammatory potency of hydrocortisone. It suppresses multiple inflammatory mediators (IL-1, IL-6, TNF-α, NF-κB), is used in injectable, oral, and topical compounded formulations for severe inflammation, adrenal insufficiency, cerebral oedema, and post-procedure management.',
  'dexamethasone-sodium-phosphate': 'Dexamethasone Sodium Phosphate is the water-soluble injectable form of dexamethasone, providing immediate onset of glucocorticoid action. Indicated for acute allergic reactions, anaphylaxis, severe asthma, cerebral oedema, and anti-emetic prophylaxis in chemotherapy. Used in compounded multi-drug injectable formulations for pain management.',
  'dihexa':         'Dihexa (PNB-0408) is a potent HGF/MET receptor agonist that crosses the blood-brain barrier to enhance hippocampal long-term potentiation. It significantly exceeds BDNF in its ability to drive synaptogenesis, improving cognitive function and memory consolidation. Applied in Alzheimer\'s disease, cognitive decline, and traumatic brain injury research.',
  'dimethyl-sulfoxide-dmso': 'DMSO (Dimethyl Sulfoxide) is a pharmaceutical-grade solvent and penetration enhancer that dramatically increases transdermal absorption of co-administered compounds by disrupting lipid bilayer packing. It also possesses intrinsic anti-inflammatory and free-radical scavenging properties. Used in compounding for topical delivery of APIs with poor percutaneous permeability.',
  'dsip':           'DSIP (Delta Sleep-Inducing Peptide) is a 9-amino acid neuropeptide that modulates sleep architecture, normalising delta slow-wave sleep and nocturnal GH secretion patterns. It reduces hypothalamic-pituitary-adrenal axis hyperactivity, lowers nocturnal cortisol, and possesses antioxidant and anti-stress properties. Applied in insomnia, circadian rhythm disorders, and stress-related conditions.',

  // ── E ──
  'edta':           'EDTA (Ethylenediaminetetraacetic Acid) is a chelating agent that forms stable complexes with divalent and trivalent metal ions (lead, cadmium, calcium, zinc). In compounding, it is used as a preservative for multi-dose injectables, a chelating agent in heavy metal detoxification protocols, and a component of anticoagulant and antimicrobial topical formulations.',
  'edta-xylitol':   'Combination of EDTA (chelating agent/preservative) and Xylitol (antimicrobial sugar alcohol) used in nasal spray formulations. EDTA disrupts bacterial biofilms by chelating divalent cations from LPS; Xylitol reduces bacterial adherence to mucosal surfaces and interferes with biofilm formation, providing a preservative-free antimicrobial nasal environment.',
  'estriol':        'Estriol (E3) is the weakest naturally occurring human oestrogen, predominant during pregnancy. As the primary oestrogen in topical and vaginal compounded formulations, it effectively addresses urogenital atrophy, vaginal dryness, and dyspareunia without the systemic proliferative risks of oestradiol. Used extensively in bio-identical HRT protocols.',
  'estradiol-pellet': 'Bioidentical 17β-Oestradiol subcutaneous pellet providing steady-state physiological oestrogen levels for 3–6 months, avoiding first-pass hepatic metabolism and peak/trough fluctuations of oral or transdermal delivery. Indicated for menopausal hormone therapy, vasomotor symptoms, urogenital atrophy, and osteoporosis prevention.',

  // ── F ──
  'follistatin-344': 'Follistatin-344 is a glycoprotein that potently and selectively neutralises myostatin (GDF-8), the primary inhibitor of skeletal muscle growth. By blocking myostatin, it removes the physiological brake on muscle fibre hypertrophy, allowing supraphysiological muscle mass increases. It also promotes adipogenesis inhibition and bone density improvement.',
  'fox-04':         'FOX04-DRI is a retro-inverso D-amino acid peptide that disrupts the interaction between the FOXO4 transcription factor and p53 in senescent cells. This interaction normally keeps senescent cells viable; disrupting it triggers selective apoptosis of senescent cells (senolytics), reducing the systemic inflammatory SASP burden associated with ageing.',
  'foxo4-10-mg':    'FOXO4-DRI is a senolytic retro-inverso peptide that selectively targets p53/FOXO4 interaction in senescent cells, triggering apoptosis of these pro-inflammatory cells without affecting healthy cells. Preclinical data shows improved physical fitness, hair growth, and tissue regeneration following senescent cell clearance.',
  'fst-344-follistatin': 'Follistatin-344 selectively binds and neutralises myostatin (GDF-8) and activin A, removing the principal inhibitory brake on skeletal muscle hypertrophy. It also enhances bone mineral density via BMP pathway augmentation. Applied in sarcopenia, muscle-wasting conditions, and performance medicine.',
  'furosemide':     'Furosemide is a loop diuretic inhibiting the Na-K-2Cl cotransporter (NKCC2) in the thick ascending limb of Henle. It produces rapid, potent sodium and fluid diuresis, reducing venous preload and pulmonary congestion. Indicated for oedema in heart failure, hepatic cirrhosis, and nephrotic syndrome, and for hypertensive crises.',

  // ── G ──
  'ghk-cu':         'GHK-Cu (Glycyl-L-histidyl-L-lysine copper complex) is an endogenous copper-binding tripeptide that stimulates collagen, elastin, and GAG synthesis by dermal fibroblasts. It activates over 4,000 genes involved in wound healing, antioxidant defence, anti-inflammatory response, and tissue remodelling. Applied topically and systemically for skin regeneration, hair follicle restoration, and tissue repair.',
  'ghrp-2':         'GHRP-2 (Growth Hormone Releasing Peptide-2) is a potent synthetic hexapeptide ghrelin receptor agonist that stimulates GH release from pituitary somatotrophs. It produces a strong GH pulse with modest elevation of cortisol and prolactin. Applied in GH deficiency, IGF-1 optimisation, cachexia, and anabolic recovery protocols.',
  'ghrp-6':         'GHRP-6 (Growth Hormone Releasing Peptide-6) is a hexapeptide ghrelin analogue that stimulates GH secretion and promotes appetite via hypothalamic ghrelin receptors. It provides a robust GH pulse with moderate cortisol increase. Used in GH restoration, body composition optimisation, and appetite stimulation in cachexia and eating disorders.',
  'gonadorelin-acetate-2mg': 'Gonadorelin Acetate is bioidentical GnRH (Gonadotropin-Releasing Hormone) that stimulates pulsatile LH and FSH release from the anterior pituitary. Used in fertility protocols, hypogonadotropic hypogonadism, and — in low-dose pulsatile regimens — to maintain testicular function and endogenous testosterone production during TRT.',
  'gw501516':       'GW501516 (Cardarine) is a PPARδ agonist that activates genes involved in fatty acid oxidation and mitochondrial biogenesis, producing exercise-like metabolic adaptations. It dramatically increases running endurance in preclinical models and improves blood lipid profiles by reducing triglycerides and LDL. Subject of WADA prohibition; research compound only.',

  // ── H ──
  'hcg':            'hCG (Human Chorionic Gonadotropin) structurally mimics LH to stimulate Leydig cell testosterone production and maintain testicular size and function during TRT. Also used in fertility protocols to trigger ovulation (trigger shot), and in male hypogonadism to restore endogenous testosterone while preserving fertility.',
  'hexarelin':      'Hexarelin is a potent synthetic hexapeptide GHRP that binds both the GHS-R1a ghrelin receptor and the CD36 scavenger receptor. It produces the most potent GH pulse of the GHRPs, also demonstrating cardioprotective effects independent of GH by reducing myocardial fibrosis and improving left ventricular function.',
  'hgh':            'Recombinant Human Growth Hormone (somatropin) is a 191-amino acid polypeptide identical to pituitary-derived GH. It activates the JAK2/STAT5 signalling pathway to stimulate IGF-1 production, lipolysis, protein synthesis, and bone mineralisation. Clinical indications include GH deficiency, adult body composition optimisation, and tissue repair.',
  'hgh-frag-176-191-5-mg': 'HGH Fragment 176-191 is the C-terminal tail of human GH responsible for its lipolytic activity, without the metabolic or proliferative effects of full-length GH. It activates beta-3 adrenergic receptors to stimulate fat mobilisation and inhibits lipogenesis via direct adipocyte action, providing a safe and targeted fat-burning strategy.',
  'hgh-fragment':   'HGH Fragment 176-191 is the C-terminal lipolytic fragment of growth hormone. It stimulates lipolysis via beta-3 adrenergic pathways and inhibits lipogenesis without the proliferative, insulin-antagonising, or water-retaining effects of intact GH. Favoured for targeted adipose reduction while preserving lean mass.',
  'hmg':            'HMG (Human Menopausal Gonadotropin) contains both FSH and LH activity derived from the urine of post-menopausal women. It stimulates follicular development and steroidogenesis. Used in controlled ovarian stimulation for IVF, and in male patients to restore spermatogenesis and endogenous testosterone via LH activity.',
  'humanin':        'Humanin is a 21-amino acid mitochondria-derived peptide (MOTS) that binds the FPRL1/FPR2 receptor and the gp130/CNTFR complex. It protects neurons from Alzheimer\'s-associated amyloid toxicity, preserves mitochondrial function under ischaemic stress, and extends cellular lifespan by activating STAT3 survival signalling.',
  'hydroquinone':   'Hydroquinone inhibits tyrosinase (the rate-limiting enzyme in melanin synthesis) and melanosome transfer, reducing hyperpigmentation. Used in compounded formulations (2–10%) for melasma, post-inflammatory hyperpigmentation, and solar lentigo under medical supervision. Often combined with tretinoin and corticosteroids in triple-combination depigmentation formulas.',

  // ── I ──
  'igf-1':          'IGF-1 (Insulin-like Growth Factor 1) is the primary mediator of GH anabolic effects, produced predominantly in the liver. It activates IGF-1R/IRS-1/PI3K/Akt signalling to drive protein synthesis, muscle hypertrophy, adipose reduction, bone mineralisation, and neurogenesis. Applied in GH deficiency, sarcopenia, and tissue repair protocols.',
  'igf-1-lr3':      'IGF-1 LR3 is a long-acting analogue of IGF-1 with an arginine substitution at position 3 and a 13-amino acid N-terminal extension that reduces IGF-binding protein affinity by 1000×. This dramatically extends its half-life from minutes to hours, providing sustained anabolic signalling for muscle hypertrophy, fat loss, and tissue repair.',
  'igf-lr3':        'IGF LR3 is the long-acting extended form of IGF-1 with reduced IGF-binding protein affinity, extending plasma half-life to approximately 20–30 hours. It provides sustained activation of IGF-1R/PI3K/Akt anabolic signalling for muscle hypertrophy, anti-catabolism, adipose reduction, and connective tissue repair.',
  'ipamorelin':     'Ipamorelin is the most selective synthetic GHRP, agonising the pituitary ghrelin receptor (GHS-R1a) without elevating cortisol, prolactin, or ACTH. It produces clean, dose-dependent pulsatile GH release and is the preferred GHRP component in combination GH-optimisation protocols for its ideal safety and selectivity profile.',
  'iodine':         'Pharmaceutical-grade Iodine API provides the essential halogen required for thyroid hormone (T3, T4) synthesis. It supports thyroid function, is compounded in topical antiseptic formulations (Lugol\'s solution, povidone-iodine), and is used in iodine supplementation protocols for hypothyroidism management and breast tissue health.',
  'ivermectin':     'Ivermectin is a macrocyclic lactone anthelmintic and antiparasitic agent that binds glutamate-gated chloride channels in invertebrate nerve and muscle cells, causing paralysis and death. Compounded in multiple concentrations for demodex mite-associated rosacea (topical 1%), strongyloidiasis and onchocerciasis (oral), and scabies treatment.',

  // ── K ──
  'kisspeptin':     'Kisspeptin (Metastin) is the endogenous ligand for the KISS1R receptor in hypothalamic GnRH neurons, functioning as the master regulator of the hypothalamic-pituitary-gonadal (HPG) axis. It drives pulsatile GnRH release, triggering downstream LH/FSH secretion. Applied in hypogonadism, fertility stimulation, and HPG axis diagnostic testing.',
  'kisspeptin-10':  'Kisspeptin-10 (KP-10, aa 112–121) is the minimal active fragment of kisspeptin that fully activates KISS1R. It triggers pulsatile GnRH and downstream LH/FSH release, providing a targeted tool for HPG-axis stimulation in hypogonadism diagnosis and treatment, and in fertility protocols for ovulation induction.',
  'kpv':            'KPV (Lys-Pro-Val) is the C-terminal tripeptide of α-melanocyte-stimulating hormone (α-MSH) that selectively activates melanocortin receptors (MC1R/MC3R) to suppress NF-κB-mediated inflammatory cascades. It effectively reduces GI inflammation and mucosal damage, demonstrating efficacy in inflammatory bowel disease and post-radiation gut injury models.',

  // ── L ──
  'ldn':            'Low-Dose Naltrexone (LDN) at 1.5–4.5 mg produces pulsatile endorphin upregulation via a rebound mechanism, modulating TLR4/NF-κB-mediated neuroimmune signalling. It reduces neuroinflammation and microglial activation. Applied in multiple sclerosis, fibromyalgia, Crohn\'s disease, and autoimmune conditions as an immunomodulatory agent.',
  'levothyroxine-sodium': 'Levothyroxine Sodium (T4) is the primary thyroid hormone replacement, providing exogenous thyroxine that is peripherally deiodinated to the active T3. It normalises basal metabolic rate, protein synthesis, cardiovascular function, and thermogenesis in hypothyroid patients. Compounded in customised doses and formulations for precise thyroid management.',
  'lidocaine-hcl':  'Lidocaine HCl is a fast-acting amide local anaesthetic and Class Ib antiarrhythmic that stabilises neuronal membranes by blocking voltage-gated sodium channels. Used in injectable (0.5–2%), topical (2–5%), and EMLA compound formulations for local anaesthesia in dermatological, dental, and procedural medicine.',
  'll-37':          'LL-37 (Cathelicidin) is the only known human cathelicidin antimicrobial peptide, cleaved from the hCAP18 precursor. It disrupts bacterial membranes, inhibits LPS-induced inflammation, promotes wound healing and angiogenesis, and modulates adaptive immunity. Applied in resistant skin infections, chronic wound management, and immunomodulation protocols.',

  // ── M ──
  'melanotan-i':    'Melanotan I (Afamelanotide) is a linear α-MSH analogue that agonises MC1R on melanocytes to increase eumelanin production, providing photoprotection. CE-marked (as Scenesse) for erythropoietic protoporphyria (EPP) to prevent phototoxic pain. Also applied in UV-light-sensitive conditions and vitiligo research.',
  'melanotan-ii':   'Melanotan II (MTII) is a cyclic α-MSH analogue that agonises MC1R, MC3R, and MC4R receptors. It produces potent photoprotective skin tanning (MC1R), sexual arousal in both sexes (MC4R), and appetite suppression (MC3R/MC4R). Delivered intranasally or subcutaneously; used in erectile dysfunction, female hypoactive sexual desire, and tanning protocols.',
  'metformin-hcl':  'Metformin HCl is a biguanide AMPK activator that reduces hepatic gluconeogenesis, improves peripheral insulin sensitivity, and modestly activates autophagy via mTOR suppression. First-line therapy for type 2 diabetes with an established cardiovascular safety profile. Increasingly studied as a longevity/anti-cancer adjuvant agent targeting the IGF-1/mTOR pathway.',
  'methionine':     'L-Methionine is an essential sulfur-containing amino acid and primary methyl group donor (as SAM). It supports hepatic methylation reactions, glutathione synthesis, and transmethylation of DNA, RNA, and histones. Used in compounded formulations for lipotropic liver support, heavy metal chelation support, and as a key component in anti-ageing methylation protocols.',
  'mgf':            'Mechano Growth Factor (MGF) is a splice variant of IGF-1 produced locally in muscle in response to mechanical loading. Its unique E-domain activates satellite cells (muscle stem cells) and upregulates protein synthesis independently of IGF-1R, providing a powerful autocrine/paracrine stimulus for muscle hypertrophy and repair after exercise or injury.',
  'mgf-peg-2mg':    'PEGylated Mechano Growth Factor extends MGF\'s plasma half-life from minutes to days while retaining its satellite cell activation and muscle hypertrophy properties. PEGylation prevents rapid enzymatic degradation, enabling systemic delivery and sustained anabolic signalling for muscle repair, sarcopenia treatment, and performance recovery.',
  'mk-677':         'MK-677 (Ibutamoren) is an orally active, non-peptide ghrelin receptor agonist that significantly increases pituitary GH secretion and elevates circulating IGF-1 without suppressing endogenous production. It improves sleep quality, increases lean body mass, reduces visceral fat, and supports bone density. Used in anti-ageing and body composition protocols.',
  'mots-c':         'MOTS-C is a mitochondria-derived peptide (MDP) encoded in the mitochondrial 12S rRNA gene that translocates to the nucleus under metabolic stress to regulate AMPK and the ARE (antioxidant response element). It improves insulin sensitivity, reduces obesity, enhances physical performance, and extends healthspan in animal models, mimicking exercise at the cellular level.',
  'mt-1-10mg':      'Melanotan I (Afamelanotide) is a stabilised linear α-MSH analogue that agonises MC1R melanocyte receptors to upregulate eumelanin production, providing UV photoprotection. CE-approved (as Scenesse) for erythropoietic protoporphyria. Also investigated for vitiligo management and UV-sensitive dermatological conditions.',

  // ── N ──
  'nadolol':        'Nadolol is a non-selective beta-adrenergic receptor blocker (beta-1/beta-2) with no intrinsic sympathomimetic activity. It reduces heart rate, myocardial contractility, and cardiac output, and blocks bronchial beta-2 receptors. Indicated for hypertension, angina pectoris, and cardiac arrhythmia management. Used in topical compounding for facial erythema/flushing in rosacea.',
  'naltrexone-hcl': 'Naltrexone HCl is a competitive opioid receptor antagonist (MOR, DOR, KOR) with high affinity for mu receptors. At standard doses (50 mg) it is used for opioid and alcohol addiction. At ultra-low doses (LDN: 1.5–4.5 mg) it produces immunomodulatory and anti-neuroinflammatory effects via TLR4 antagonism and endorphin rebound.',
  'nystatin':       'Nystatin is a polyene antifungal that binds ergosterol in fungal membranes to form pores causing ion leakage and cell death. Used in compounded oral and topical formulations for mucosal candidiasis (oral thrush, oesophageal, vaginal). It is non-absorbed systemically, making it safe for oral prophylaxis in immunocompromised patients.',

  // ── O ──
  'orlistat':       'Orlistat is a gastrointestinal lipase inhibitor that covalently blocks pancreatic and gastric lipase active sites, preventing the hydrolysis and absorption of approximately 30% of dietary fat. Indicated for medically supervised obesity treatment (BMI ≥30) and weight maintenance. Available in prescription (120 mg) and OTC (60 mg) strengths.',
  'oxytocin':       'Oxytocin is a hypothalamic nonapeptide released from the posterior pituitary that acts on OXT receptors throughout the brain and periphery. It promotes social bonding, reduces fear and cortisol, enhances neuroplasticity, and facilitates parturition and lactation. Delivered intranasally for CNS effects (anxiety, PTSD, social cognition) or IV/IM for obstetric indications.',
  'oxytocin-acetate': 'Oxytocin Acetate is the compounded form of the hypothalamic nonapeptide oxytocin. Delivered intranasally, it accesses brain OXT receptors to enhance prosocial behaviour, reduce anxiety and cortisol, and improve trust and emotional processing. Used in PTSD, social anxiety, autism spectrum disorder, and as a component of sexual wellness protocols.',
  'oxitriptan-5-htp': '5-Hydroxytryptophan (5-HTP) is the direct precursor to serotonin in the indoleamine pathway, crossing the blood-brain barrier to bypass the rate-limiting tryptophan hydroxylase step. It effectively increases central serotonin, melatonin, and β-endorphin levels. Applied for depression, anxiety, insomnia, fibromyalgia, and appetite regulation.',

  // ── P ──
  'papaverine-hcl': 'Papaverine HCl is a smooth muscle relaxant and phosphodiesterase inhibitor that reduces intracellular cAMP degradation, producing vasodilation. Used intracavernosally (combined with alprostadil and phentolamine in Tri-Mix) for erectile dysfunction, and intravascularly for vasospasm prevention during vascular surgery and stroke treatment.',
  'pe-22-28':       'PE-22-28 is a synthetic analogue of Spadin, a sortilin-derived peptide that selectively antagonises the TREK-1 (KCNK2) two-pore domain potassium channel. By blocking TREK-1, it produces rapid and sustained antidepressant effects in preclinical models via enhanced serotonergic and noradrenergic transmission, without the side effects of traditional antidepressants.',
  'peg-mgf':        'PEGylated MGF is a long-acting form of Mechano Growth Factor with polymer chains attached to extend half-life from minutes to several days. It activates muscle satellite cells for hypertrophy and repair, provides anti-inflammatory and anti-fibrotic signals in damaged tissue, and enables practical dosing schedules for muscle-wasting conditions and athletic recovery.',
  'pinealon':       'Pinealon is a synthetic tripeptide (Glu-Asp-Arg) epiphysis bioregulator developed by the St. Petersburg Institute of Bioregulation. It reduces melatonin suppression with ageing by stimulating pinealocyte protein synthesis and gene expression, supporting circadian rhythm normalisation, antioxidant defence, and cognitive function in ageing populations.',
  'pnc-27':         'PNC-27 is a 32-amino acid anticancer peptide that incorporates a p53 transactivation domain sequence fused to an HDM-2 binding domain. It selectively inserts into the plasma membranes of cancer cells that aberrantly express HDM-2, forming pores that cause rapid necrosis of cancer cells while leaving normal cells unaffected.',
  'prasterone-dhea': 'Prasterone (DHEA) is the endogenous adrenal androgen precursor to oestrogens and testosterone. In vaginal formulations (intrarosa), it locally restores urogenital tissue without systemic hormonal effects. Systemically, DHEA supplementation supports adrenal androgen levels, mood, bone density, and sexual function, particularly in women with adrenal insufficiency.',
  'pregnenolone':   'Pregnenolone is the master neurosteroid precursor synthesised from cholesterol in the adrenal cortex and CNS mitochondria. It modulates GABA-A and NMDA receptor activity, enhances memory consolidation and cognitive function, and serves as the biosynthetic precursor to DHEA, progesterone, cortisol, and sex hormones. Applied in neuroendocrine optimisation protocols.',
  'prilocaine':     'Prilocaine is a medium-acting amide local anaesthetic that blocks voltage-gated sodium channels. Less cardiotoxic than lidocaine and widely used in EMLA (5% eutectic mixture with lidocaine) for topical anaesthesia before dermatological procedures, venipuncture, and laser treatments. Also used in dental blocks and regional anaesthesia.',
  'progesterone':   'Bioidentical Progesterone (P4) is structurally identical to endogenous ovarian progesterone. It opposes oestrogen-induced endometrial proliferation, supports luteal phase function, reduces anxiety via GABA-A neurosteroid modulation (allopregnanolone), and protects against breast cancer. Used in BHRT and fertility protocols via oral, vaginal, topical, or injectable compounded routes.',
  'prostamax':      'Prostamax is a prostate-specific bioregulator peptide developed by the St. Petersburg Institute of Bioregulation. It selectively stimulates prostate gland gene expression and protein synthesis, normalising prostatic function, reducing prostate hypertrophy-associated inflammation, and supporting urological health in ageing men.',
  'pt-141':         'PT-141 (Bremelanotide) is a cyclic heptapeptide analogue of alpha-MSH that potently agonises hypothalamic melanocortin MC3R and MC4R receptors, activating the central neural pathway of sexual arousal independently of vascular mechanisms. FDA-approved (Vyleesi) for hypoactive sexual desire disorder (HSDD) in premenopausal women. Also used for erectile dysfunction.',

  // ── S ──
  'sermorelin':     'Sermorelin (GHRH 1-29 NH₂) is the biologically active N-terminal fragment of Growth Hormone Releasing Hormone that stimulates pituitary somatotrophs to produce and secrete GH in a pulsatile, physiological pattern. Unlike exogenous GH, sermorelin preserves the pituitary GH axis. Indicated for adult-onset GH deficiency, anti-ageing, and body composition optimisation.',
  'serrapeptase-300000spu': 'Serrapeptase (Serratiopeptidase) is a serine protease derived from Serratia marcescens that selectively degrades fibrin, non-living tissue, and inflammatory mediators without affecting healthy tissue. At 300,000 SPU/capsule, it provides potent systemic anti-inflammatory, anti-fibrotic, anti-oedematous, and mucolytic effects for chronic inflammation, post-surgical recovery, and fibrocystic conditions.',
  'slimaluma':      'Slimaluma® is a standardised Caralluma fimbriata extract (5:1, 10% pregnane glycosides) clinically demonstrated to suppress appetite by modulating the hypothalamic leptin pathway and inhibiting fat synthesis enzymes (fatty acid synthase, citrate lyase). Multiple double-blind RCTs show significant reductions in waist circumference, body weight, and energy intake vs placebo.',
  'slu-pp-332':     'SLU-PP-332 is a synthetic agonist of the ERR (Oestrogen-Related Receptor) alpha and delta nuclear receptors, transcription factors that regulate mitochondrial biogenesis and oxidative metabolism. It mimics the molecular adaptations of endurance exercise at the genomic level, improving fat oxidation, insulin sensitivity, and endurance capacity without physical activity.',
  'snap-8':         'SNAP-8 (Acetyl Glutamyl Heptapeptide-3) is an extended hexapeptide analogue of Acetylhexapeptide-3 that inhibits the SNARE complex formation with 8-amino acid greater efficacy than Argireline. By reducing synaptic vesicle fusion at facial neuromuscular junctions, it decreases muscle contraction and attenuates the appearance of fine lines and wrinkles.',
  'sodium-ascorbate': 'Sodium Ascorbate is the buffered, mineral salt form of Vitamin C (ascorbic acid). It donates electrons as a reducing agent to neutralise reactive oxygen species, regenerate tocopherol from tocopheroxyl radicals, stimulate collagen synthesis (hydroxylation of proline and lysine), and support immune function. Preferred over ascorbic acid for IV high-dose protocols due to neutral pH.',
  'ss-31':          'SS-31 (Elamipretide) is a mitochondria-targeting tetrapeptide that selectively concentrates in the inner mitochondrial membrane, interacting with cardiolipin to stabilise respiratory supercomplex assembly. It reduces electron leak, restores ATP synthesis efficiency, reduces mitochondrial ROS, and prevents cytochrome c release. Applied in heart failure, mitochondrial myopathies, and age-related mitochondrial decline.',
  'survodutide-10mg': 'Survodutide is a novel dual GLP-1/glucagon receptor co-agonist. The GLP-1 component improves glycaemic control and induces satiety; the glucagon component independently increases energy expenditure and hepatic fat oxidation. Phase 2 data shows superior weight reduction vs GLP-1 monotherapy with complementary metabolic effects relevant to MASLD/NASH.',

  // ── T ──
  'tacrolimus':     'Tacrolimus (FK506) is a calcineurin inhibitor macrolide that suppresses T-lymphocyte activation by blocking IL-2 production. In compounded 0.03–0.1% topical formulations, it treats atopic dermatitis, vitiligo, and severe psoriasis without steroid-associated skin atrophy. Systemic use for solid organ transplant rejection prevention.',
  'tb-10-mg-bpc-10-mg-ghk-50-mg': 'Triple-combination regenerative stack: TB-500/Thymosin Beta-4 (actin-mediated cell migration and angiogenesis), BPC-157 (VEGFR2/eNOS tissue repair), and GHK-Cu (collagen/elastin remodelling and gene activation). Together they comprehensively address the tissue repair cascade from inflammatory resolution through structural matrix rebuilding.',
  'tesamorelin':    'Tesamorelin (GHRH analogue, FDA-approved as Egrifta) is a modified form of GRF(1-44)-amide that stimulates pulsatile GH release from somatotrophs. It is specifically approved to reduce HIV-associated lipodystrophy visceral fat accumulation, and is increasingly used in anti-ageing medicine for IGF-1 restoration, body composition improvement, and cognitive support.',
  'tesamorelin-ipamorelin': 'Synergistic dual GH-axis stimulation stack: Tesamorelin amplifies GHRH signalling for sustained GH release; Ipamorelin selectively agonises pituitary ghrelin receptors without cortisol elevation. Together they produce supraadditive GH pulses for superior body composition improvement, IGF-1 restoration, sleep enhancement, and metabolic optimisation.',
  'testagen':       'Testagen is a tetrapeptide (Lys-Glu-Asp-Gly) bioregulator specific to testicular tissue that stimulates Leydig cell steroidogenesis gene expression and testosterone production. Developed by the St. Petersburg Institute of Bioregulation, it supports natural androgen restoration in hypogonadism and age-related testosterone decline without direct hormone supplementation.',
  'testosterone':   'Testosterone is the primary endogenous androgen produced predominantly in Leydig cells. It drives muscle protein synthesis, bone mineralisation, erythropoiesis, libido, and cognitive function via androgen receptor signalling. Compounded in bioidentical creams, injectables, troches, and pellets for TRT, androgen deficiency, and female sexual wellness protocols.',
  'thymagen':       'Thymagen (Glu-Trp) is a thymus bioregulator dipeptide that stimulates thymocyte differentiation and T-lymphocyte maturation, restoring cell-mediated immunity in immunosenescence. Developed by the St. Petersburg Institute of Bioregulation, it supports immune function restoration in ageing, immunodeficient states, and post-infectious recovery.',
  'thymalin':       'Thymalin is a polypeptide extract from calf thymus containing thymic hormones that regulate T-cell differentiation, maturation, and immune homeostasis. It improves natural killer cell activity, normalises T-cell subsets, and reduces pro-inflammatory cytokines. Applied in immune restoration, chronic immunodeficiency, and longevity protocols in ageing populations.',
  'thymogen':       'Thymogen (Glu-Trp) is a synthetic thymic dipeptide bioregulator that mimics the immunomodulatory effects of thymopoietin. It stimulates T-cell differentiation, normalises CD4:CD8 ratios, and restores age-related immune decline. Used in chronic immunodeficiency, frequent infections, and as a component of comprehensive longevity-medicine protocols.',
  'thymosin-alpha': 'Thymosin Alpha-1 (Tα1, Zadaxin) is a 28-amino acid thymic hormone that activates dendritic cells and NK cells, upregulates TLR expression on innate immune cells, and enhances T-helper-1 cytokine production. It is used to boost anti-viral immunity (hepatitis B, C, COVID-19), treat immunodeficiency, and as an adjuvant in cancer immunotherapy.',
  'thymosin-alpha-1': 'Thymosin Alpha-1 (Tα1) is a naturally occurring thymic peptide hormone that potentiates dendritic cell maturation and T-cell-mediated immunity via TLR2/TLR9 pathway activation. Registered in 35+ countries for hepatitis B and C, and studied in COVID-19 and oncological immunotherapy. Restores immune competence in immunosuppressed and ageing patients.',
  'thymosin-beta':  'Thymosin Beta-4 (TB-4) is a 43-amino acid peptide that modulates actin dynamics, promotes cell migration, angiogenesis, and matrix remodelling. It reduces inflammatory markers, accelerates wound closure, supports myocardial regeneration, and protects neurons from oxidative damage. Applied across musculoskeletal repair, cardiac regeneration, and neurological protection protocols.',

  // ── V ──
  'vancomycin-hcl': 'Vancomycin HCl is a glycopeptide antibiotic that inhibits bacterial cell wall synthesis by binding to D-Ala-D-Ala termini of peptidoglycan precursors. Compounded at 5–10 mg/mL for oral MRSA decolonisation, intrathecal administration for CNS infections, and as part of antibiotic-impregnated cement in orthopaedic surgery. IV use for serious Gram-positive infections.',
  'vit-d3-10000iu-k2': 'High-potency Vitamin D3 (Cholecalciferol, 10,000 IU) combined with Vitamin K2 (Menaquinone-7, 200 mcg). D3 stimulates intestinal calcium absorption and immune modulation via VDR nuclear receptors; K2 activates osteocalcin and matrix Gla protein to direct calcium into bone rather than arteries, preventing vascular calcification at high D3 doses.',
  'vitamin-e-acetate-50-powder': 'Alpha-Tocopheryl Acetate 50% Powder (in maltodextrin/silica carrier) is a free-flowing, water-dispersible form of Vitamin E acetate. It provides antioxidant protection in dry and aqueous compounding environments. The esterified acetate form is hydrolysed by skin esterases to active alpha-tocopherol at the site of application.',

  // ── Additional bundles/stacks ──
  'advanced-weight-loss': 'Precision-compounded multi-component formulation combining metabolically active peptides and small molecules targeting adipose lipolysis, appetite suppression, and energy expenditure upregulation. Designed for subcutaneous administration within medically supervised weight-management programmes.',
  'anti-aging-and-immunity-bundle': 'Curated clinical peptide stack targeting the hallmarks of ageing: telomere attrition, cellular senescence, mitochondrial dysfunction, and immune dysregulation. Each component is independently HPLC-verified for purity and potency.',
  'cellular-repair-and-energy-bundle': 'Precision peptide stack activating mitochondrial biogenesis, cellular autophagy, and tissue repair via AMPK/PGC-1α energy-sensing pathways combined with growth-factor mimetics. Restores cellular vitality and accelerates recovery from metabolic and oxidative stress.',
  'health-optimisation-bundle': 'Comprehensive wellness stack combining validated peptides addressing longevity, metabolic health, immune function, and cognitive performance, each targeting evidence-based biological pathways for systemic health optimisation.',
  'skin-tissue-regeneration-stack': 'Regenerative peptide stack targeting collagen synthesis, angiogenesis, fibroblast proliferation, and anti-inflammatory pathways for comprehensive skin rejuvenation, post-procedure recovery, and chronic wound management.',
  'wolverine-repair-bundle': 'High-potency recovery stack combining BPC-157 and TB-500 with complementary repair peptides to maximise musculoskeletal, tendon, and ligament regeneration following acute injury or intensive training loads.',
  'oxytocin-methylene-blue': 'Intranasal combination of Oxytocin and Methylene Blue delivered via the nose-to-brain transcribiform pathway. Oxytocin modulates HPA-axis stress response and promotes neuroplasticity; Methylene Blue acts as a mitochondrial electron shuttle, improving ATP production, reducing ROS, and enhancing cognitive performance and mood.',
  'pt-141-oxytocin': 'Intranasal combination of PT-141 (Bremelanotide) and Oxytocin targeting central melanocortin pathways for sexual arousal and prosocial bonding. PT-141 activates hypothalamic MC3R/MC4R receptors for arousal; Oxytocin reduces anxiety and enhances bonding via central OXT receptors.',
};

function isGeneric(t) { return typeof t === 'string' && t.includes(MARKER); }
function getReplacement(id) {
  if (D[id]) return D[id];
  const alt = id.replace(/_/g, '-');
  return D[alt] || null;
}

async function main() {
  console.log(`\n🔍  Scanning Firestore products…`);
  if (DRY) console.log(`⚠️   DRY RUN – no writes\n`);
  const snap = await db.collection('products').get();
  console.log(`📦  Total docs: ${snap.size}\n`);
  const hits = [];
  for (const doc of snap.docs) {
    const d = doc.data();
    const gD = isGeneric(d.description), gA = isGeneric(d.aiDescription);
    if (gD || gA) hits.push({ id: doc.id, name: d.name||doc.id, gD, gA, r: getReplacement(doc.id) });
  }
  const ok = hits.filter(h=>h.r), nope = hits.filter(h=>!h.r);
  console.log(`Found ${hits.length} generic descriptions:`);
  console.log(`  ✅ Will fix: ${ok.length}`);
  console.log(`  ❌ No entry: ${nope.length}\n`);
  for (const h of hits) {
    const icon = h.r ? '✅' : '❌';
    console.log(`  ${icon} [${h.id}]  ${h.name}`);
    if (h.r) console.log(`      → ${h.r.slice(0, 95)}…`);
  }
  if (!DRY && ok.length) {
    console.log('\n🚀  Writing to Firestore…');
    let batch = db.batch(), c = 0, tot = 0;
    for (const h of ok) {
      const u = {};
      if (h.gD) u.description   = h.r;
      if (h.gA) u.aiDescription = h.r;
      batch.update(db.collection('products').doc(h.id), u);
      c++; tot++;
      if (c >= 400) { await batch.commit(); console.log(`  ✓ batch ${c}`); batch = db.batch(); c = 0; }
    }
    if (c) { await batch.commit(); console.log(`  ✓ final batch ${c}`); }
    console.log(`\n✅  Updated ${tot} products.`);
  }
  if (nope.length) {
    console.log('\n⚠️   Still needing manual description:');
    nope.forEach(h => console.log(`   - [${h.id}]  ${h.name}`));
  }
  process.exit(0);
}
main().catch(e => { console.error('❌', e.message); process.exit(1); });
